fun creationOrder(needs: Map<String, List<String>>, wanted: List<String>): List<String> {
    val order = LinkedHashSet<String>()
    fun visit(name: String) {
        if (name in order) return                    // already in the plan
        needs[name].orEmpty().forEach(::visit)       // everything it needs first
        order += name                                // then the name itself: post-order
    }
    wanted.forEach(::visit)
    return order.toList()
}
// [Route, Driver, Truck, TapeRoll, Packer, Crew, MovingDay]

