static List<String> creationOrder(Map<String, List<String>> needs, List<String> wanted) {
    LinkedHashSet<String> order = new LinkedHashSet<>();
    for (String name : wanted) visit(name, needs, order);
    return new ArrayList<>(order);
}

static void visit(String name, Map<String, List<String>> needs, LinkedHashSet<String> order) {
    if (order.contains(name)) return;                                // already in the plan
    for (String d : needs.getOrDefault(name, List.of())) visit(d, needs, order);
    order.add(name);                                                 // post-order
}
